import AudiateCore

extension Sound {
    /// File name in Resources/Samples (generated by tools/make_samples.sh).
    public var sampleName: String {
        switch self {
        case .hiHat: "hihat_open"
        case .click(let accented): accented ? "beat_strong" : "beat_weak"
        case .downbeat: "beat_down"
        }
    }
}

extension SampleBank {
    public static let tapSampleName = "tap"
}
